+size_t ThreadsList::size_in_bytes() const {
+  size_t size = sizeof(*this);
+  if (_length != 0) {
+    // Add the size of the pointer array, and its null-terminator.
+    size += (size_t(_length) + 1) * sizeof(JavaThread *);
+  }
+  return size;
+}
